<script setup>
import { computed, onMounted } from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import { useAppStore } from '../../stores/app.store';
const store = useAppStore();
onMounted(() => store.load('trips'));
const bores = computed(() => (store.data.freeBores || []).filter(b => Number(b.id_station) === Number(store.form.id_station_arrivee)));
</script>
<template><AppLayout><section class="stack"><div class="intro"><p class="eyebrow">Mobilité personnelle</p><h2>Mes trajets</h2></div><div class="grid two"><article class="card"><p class="eyebrow">Trajet en cours</p><template v-if="store.data.openTrip"><h2>{{ store.data.openTrip.numero_serie }}</h2><p>Départ : {{ store.data.openTrip.station_depart_nom }}</p><label>Station d’arrivée<select v-model="store.form.id_station_arrivee"><option value="">Choisir</option><option v-for="s in store.data.stations" :key="s.id_station" :value="s.id_station">{{ s.nom }}</option></select></label><label>Borne libre<select v-model="store.form.id_borne_arrivee"><option value="">Choisir</option><option v-for="b in bores" :key="b.id_borne" :value="b.id_borne">Borne {{ b.id_borne }}</option></select></label><button class="primary" @click="store.action('return_trip',{id_trajet:store.data.openTrip.id_trajet,id_station_arrivee:store.form.id_station_arrivee,id_borne_arrivee:store.form.id_borne_arrivee},'trips')">Restituer</button></template><template v-else><h2>Aucun trajet</h2><RouterLink class="primary" to="/stations">Voir les stations</RouterLink></template></article><article class="card"><p class="eyebrow">Réservation</p><h2>{{ store.data.reservation?.numero_serie || 'Aucune réservation' }}</h2><p>{{ store.data.reservation?.station_nom || 'Réservez un vélo disponible.' }}</p><button v-if="store.data.reservation?.statut==='active'" class="secondary" @click="store.action('cancel_reservation',{id_reservation:store.data.reservation.id_reservation},'trips')">Annuler</button></article></div><article class="card table-card"><header><p class="eyebrow">Historique</p><h2>Derniers trajets</h2></header><table><tr><th>Date</th><th>Vélo</th><th>Départ</th><th>Arrivée</th><th>Coût</th><th>Note</th></tr><tr v-for="t in store.data.trips" :key="t.id_trajet"><td>{{ $formatDateTime(t.date_depart) }}</td><td>{{ t.numero_serie }}</td><td>{{ t.station_depart_nom }}</td><td>{{ t.station_arrivee_nom || 'En cours' }}</td><td>{{ t.cout_facture }} €</td><td><button v-if="t.date_arrivee&&!t.note_evaluation" class="link small" @click="store.action('rate_trip',{id_trajet:t.id_trajet,note_evaluation:5},'trips')">Noter 5/5</button><span v-else>{{ t.note_evaluation || '—' }}</span></td></tr></table></article></section></AppLayout></template>
